/** Exact F_2 fibre arithmetic. Every displayed count is derived from subsets. */
export function pairVector(subset,n){const N=2**n,S=new Set(subset);if(S.size!==subset.length||subset.some(x=>!Number.isInteger(x)||x<0||x>=N))throw Error('Invalid fibre subset');return Array.from({length:N-1},(_,d)=>{const a=d+1;let t=0;for(const x of S)if(x<(x^a)&&S.has(x^a))t++;return t;});}
export function fibreAudit(fibres,n){const N=2**n;if(fibres.length!==N)throw Error('Invalid base');const vectors=fibres.map(s=>pairVector(s,n)),sums=Array.from({length:N-1},(_,d)=>{let s=0;for(let a=0;a<N;a++){const b=a^(d+1);if(a<b)s+=vectors[a][d]*vectors[b][d];}return s;});return{weight:fibres.reduce((s,f)=>s+f.length,0),vectors,sums,threshold:N/2,covered:sums.filter(x=>x>=N/2).length,energy:vectors.reduce((s,v)=>s+v.reduce((a,x)=>a+x*x,0),0)};}
export function starFibres(n,assignments){const N=2**n;return Array.from({length:N},(_,a)=>a===0?Array.from({length:N},(_,i)=>i):[0,assignments?.[a-1]??a]);}
export function puzzleAssignments(n){const D=2**n-1;return Array.from({length:D},(_,i)=>(i+1)%D+1);}
export function directionOptions(a,n){const D=2**n-1;return [...new Set([a,a%D+1,(a+1)%D+1])].sort((x,y)=>x-y);}
export function ringWitnessAudit(points,n){const K=new Set(points.map(x=>x.join(','))),dirs=[];for(let code=0;code<4**n;code++){let z=code;const d=Array.from({length:n},()=>{const v=z%4;z=Math.floor(z/4);return v;});if(!d.some(x=>x%2))continue;const neg=d.map(x=>(4-x)%4);if(d.join(',')>neg.join(','))continue;const line=points.find(a=>[0,1,2,3].every(t=>K.has(a.map((x,i)=>(x+t*d[i])%4).join(','))));dirs.push({direction:d,line:line?Array.from({length:4},(_,t)=>line.map((x,i)=>(x+t*d[i])%4)):null});}return{points:K.size,directions:dirs.length,covered:dirs.filter(d=>d.line).length,lines:dirs};}
export function awardStage(state,n){state.kakeya??={version:1,assignments:{},solved:[]};if(state.kakeya.solved.includes(n))return 0;state.kakeya.solved.push(n);const credits={2:10,3:20,4:40}[n]||0;state.gold+=credits;return credits;}
export {installWayglassProps as installStations} from './wayglass-model.js?v=5.11.0';
